<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Throwable; use Pterodactyl\Services\Allocations\FindAssignableAllocationService; class ServerPlatform { public static function detect(ServerFiles $client): ?array { $root = $client->listFiles('/'); if ($root === null) { return null; } $names = array_column($root, 'name'); $has = fn (string $name) => in_array($name, $names, true); if ($has('.fabric') || $has('fabric-server-launcher.properties')) { return ['platform' => 'fabric', 'directory' => '/mods']; } if ($has('.paper')) { return ['platform' => 'paper', 'directory' => '/plugins']; } if ($has('spigot.yml') || $has('bukkit.yml')) { return ['platform' => 'spigot', 'directory' => '/plugins']; } $loader = self::modLoader($client, $names); if ($loader !== null) { return ['platform' => $loader, 'directory' => '/mods']; } return null; } private static function modLoader( ServerFiles $client, array $names, ): ?string { $libraries = array_map( fn (array $entry) => mb_strtolower((string) ($entry['name'] ?? '')), $client->listFiles('/libraries/net') ?? [], ); foreach (['neoforged' => 'neoforge', 'minecraftforge' => 'forge', 'fabricmc' => 'fabric'] as $library => $platform) { if (in_array($library, $libraries, true)) { return $platform; } } foreach ($names as $name) { $lower = mb_strtolower($name); if (! str_contains($lower, 'installer')) { continue; } if (str_contains($lower, 'neoforge')) { return 'neoforge'; } if (str_contains($lower, 'fabric')) { return 'fabric'; } if (str_contains($lower, 'forge')) { return 'forge'; } } return null; } public static function claimPort(ServerFiles $client): ?array { $server = $client->server; $before = array_map(fn (array $allocation) => $allocation['port'], $client->allocations()); try { if (!self::assign($server)) { return null; } } catch (Throwable) { return null; } foreach ($server->allocations()->get() as $allocation) { if (in_array((int) $allocation->port, $before, true)) { continue; } return ['ip' => (string) $allocation->ip, 'port' => (int) $allocation->port]; } return null; } private static function assign(\Pterodactyl\Models\Server $server): bool { try { $claimed = \Illuminate\Support\Facades\DB::transaction(function () use ($server) { if ($server->allocations()->lockForUpdate()->count() >= (int) $server->allocation_limit) { return false; } $allocation = app(FindAssignableAllocationService::class)->handle($server); $allocation->update(['server_id' => $server->id, 'notes' => 'Geyser (Bedrock)']); return true; }); } catch (Throwable) { return false; } if ($claimed) { $server->load('allocations'); } return $claimed; } public static function isPlugin(string $platform): bool { return in_array($platform, ['paper', 'spigot'], true); } } 